// Shapes, prompts and validators for teacher documents (TeacherDoc.content).
// Shared by the API routes and the client editors.

import { parseExam } from './exam';
import { sourceBlock, type SourceFile } from './source';

export type DocType = 'slides' | 'quiz' | 'lesson' | 'exam';
/** Types generated by /api/teacher/generate (exam papers have their own route). */
export type GeneratedDocType = 'slides' | 'quiz' | 'lesson';

export const DOC_TYPES: Record<DocType, { label: string; plural: string; path: string }> = {
  exam:   { label: 'Exam paper',  plural: 'Exam Papers',  path: '/teacher/exams' },
  slides: { label: 'Slide deck',  plural: 'Slides',       path: '/teacher/slides' },
  quiz:   { label: 'Quiz',        plural: 'Quizzes',      path: '/teacher/quizzes' },
  lesson: { label: 'Lesson plan', plural: 'Lesson Plans', path: '/teacher/lesson-plans' },
};

export const GRADES = ['6', '7', '8', '9', '10', '11', '12', 'College'];
export const LANGUAGES = [
  'English', 'Hindi', 'Tamil', 'Telugu', 'Bengali', 'Marathi',
  'Kannada', 'Malayalam', 'Gujarati', 'Punjabi',
];

// ── Slides ───────────────────────────────────────────────────────────

/*
 * Visual contract (renderer, editor, PPTX export and present mode all follow it):
 * - 'title':   emoji + title + subtitle; `image` (if any) beside it.
 * - 'image':   `image` is the hero; bullets are short captions beside it.
 * - 'diagram': `diagram` is the hero under the title; up to 2 bullets as a caption.
 * - 'bullets' / 'summary' / 'quote': text, with `image` (if any) beside it,
 *   otherwise the slide `emoji` as a large decorative icon.
 * - 'two-column': two text columns only.
 * `diagram` is only drawn on 'diagram' slides; `image` is ignored on 'two-column'/'diagram'.
 * Present mode reveals items one click at a time in REVEAL ORDER: bullets, then
 * `right` (two-column), then diagram items. Title, emoji and image are always visible.
 */
export type SlideLayout = 'title' | 'bullets' | 'image' | 'diagram' | 'two-column' | 'quote' | 'summary';
export const SLIDE_LAYOUTS: SlideLayout[] = ['title', 'bullets', 'image', 'diagram', 'two-column', 'quote', 'summary'];

/** flow = left-to-right steps with arrows; cycle = items around a loop; cards = grid of concepts. */
export type DiagramKind = 'flow' | 'cycle' | 'cards';
export const DIAGRAM_KINDS: DiagramKind[] = ['flow', 'cycle', 'cards'];

export interface DiagramItem {
  emoji: string;
  /** ≤ 4 words */
  label: string;
  /** ≤ 12 words, may be empty */
  detail: string;
}

export interface SlideDiagram {
  kind: DiagramKind;
  items: DiagramItem[]; // 2–6
}

/** A free-licensed image from Wikimedia Commons (see src/lib/commons.ts). */
export interface SlideImage {
  /** Thumbnail URL on upload.wikimedia.org / thumb.wikimedia.org (≈1024px wide). */
  url: string;
  width: number;
  height: number;
  /** File title without the "File:" prefix. */
  title: string;
  /** Author, plain text. */
  credit: string;
  /** e.g. "CC BY-SA 4.0", "Public domain". */
  license: string;
  /** Commons file page, for attribution links. */
  page: string;
}

export interface Slide {
  layout: SlideLayout;
  title: string;
  subtitle: string;
  bullets: string[];
  /** Second column for the two-column layout. */
  right: string[];
  /** What to draw/show on the slide, as guidance for the teacher. */
  visual: string;
  notes: string;
  /** One emoji that represents the slide (may be empty). */
  emoji: string;
  /** English search terms used to find `image` (2–6 words). */
  imageQuery: string;
  image: SlideImage | null;
  diagram: SlideDiagram | null;
}

/** Number of click-to-reveal steps in present mode (see REVEAL ORDER above). */
export function revealSteps(s: Slide): number {
  if (s.layout === 'title' || s.layout === 'quote') return 0;
  const bullets = s.bullets.filter(Boolean).length;
  // diagram slides only draw two caption bullets
  const text = (s.layout === 'diagram' ? Math.min(2, bullets) : bullets)
    + (s.layout === 'two-column' ? s.right.filter(Boolean).length : 0);
  return text + (s.layout === 'diagram' && s.diagram ? s.diagram.items.length : 0);
}

const IMAGE_HOST = /^https:\/\/(upload|thumb)\.wikimedia\.org\//;

export type SlideTheme = 'saffron' | 'indigo' | 'midnight';
export const SLIDE_THEMES: Record<SlideTheme, { bg: string; fg: string; accent: string; muted: string }> = {
  saffron:  { bg: 'FFFFFF', fg: '1A1A2E', accent: 'FF6B2C', muted: '6B7280' },
  indigo:   { bg: 'F5F5FF', fg: '1E1B4B', accent: '4F46E5', muted: '6B7280' },
  midnight: { bg: '0F0F1A', fg: 'F0F0FF', accent: 'FF8A50', muted: '9CA3AF' },
};

export interface SlidesContent {
  theme: SlideTheme;
  slides: Slide[];
}

export function emptySlide(layout: SlideLayout = 'bullets'): Slide {
  return {
    layout, title: 'New slide', subtitle: '', bullets: [''], right: [], visual: '', notes: '',
    emoji: '', imageQuery: '', image: null, diagram: layout === 'diagram' ? { kind: 'flow', items: [] } : null,
  };
}

// ── Quiz ─────────────────────────────────────────────────────────────

export type QuestionType = 'mcq' | 'truefalse' | 'short';

export interface QuizQuestion {
  type: QuestionType;
  question: string;
  /** Options for mcq (4) and truefalse (["True","False"]); empty for short. */
  options: string[];
  /** Index into options for mcq/truefalse; -1 for short answer. */
  correct: number;
  /** Model answer for short-answer questions. */
  answer: string;
  explanation: string;
  marks: number;
}

export interface QuizContent {
  instructions: string;
  difficulty: 'easy' | 'medium' | 'hard';
  questions: QuizQuestion[];
}

export function emptyQuestion(type: QuestionType = 'mcq'): QuizQuestion {
  return {
    type,
    question: '',
    options: type === 'mcq' ? ['', '', '', ''] : type === 'truefalse' ? ['True', 'False'] : [],
    correct: type === 'short' ? -1 : 0,
    answer: '',
    explanation: '',
    marks: 1,
  };
}

/** Auto-gradable questions — what students answer in an assigned quiz. */
export const isAutoGraded = (q: QuizQuestion) => q.type !== 'short' && q.correct >= 0;

// ── Lesson plan ──────────────────────────────────────────────────────

export interface LessonSection {
  title: string;
  minutes: number;
  teacher: string;
  students: string;
}

export interface LessonContent {
  duration: number;
  objectives: string[];
  prerequisites: string[];
  materials: string[];
  sections: LessonSection[];
  assessment: string[];
  homework: string[];
  differentiation: string;
  boardWork: string;
}

// ── Validation (LLM output is untrusted) ─────────────────────────────
// `strict` is for AI output (reject thin results); edits only need one item.

const str = (v: unknown, max = 2000) => (typeof v === 'string' ? v.trim().slice(0, max) : '');
const strList = (v: unknown, maxItems = 12) =>
  (Array.isArray(v) ? v : []).map(x => str(x, 500)).filter(Boolean).slice(0, maxItems);
const num = (v: unknown, fallback: number, min: number, max: number) => {
  const n = Number(v);
  return Number.isFinite(n) ? Math.max(min, Math.min(max, Math.round(n))) : fallback;
};
const obj = (v: unknown) => (v && typeof v === 'object' ? (v as Record<string, unknown>) : {});

export function parseSlides(value: unknown, strict = true): SlidesContent | null {
  const raw = obj(value);
  const list = Array.isArray(raw.slides) ? raw.slides : Array.isArray(value) ? (value as unknown[]) : [];
  const slides: Slide[] = list.map(s => {
    const o = obj(s);
    const layout = SLIDE_LAYOUTS.includes(o.layout as SlideLayout) ? (o.layout as SlideLayout) : 'bullets';
    return {
      layout,
      title: str(o.title, 200) || 'Untitled',
      subtitle: str(o.subtitle, 300),
      bullets: strList(o.bullets, 8),
      right: strList(o.right, 8),
      visual: str(o.visual, 400),
      notes: str(o.notes, 2000),
      emoji: str(o.emoji, 16),
      imageQuery: str(o.imageQuery, 100),
      image: parseSlideImage(o.image),
      diagram: parseDiagram(o.diagram, strict),
    };
  });
  if (slides.length < (strict ? 3 : 1)) return null;
  const theme = (Object.keys(SLIDE_THEMES) as SlideTheme[]).includes(raw.theme as SlideTheme)
    ? (raw.theme as SlideTheme) : 'saffron';
  return { theme, slides: slides.slice(0, 30) };
}

function parseSlideImage(value: unknown): SlideImage | null {
  const o = obj(value);
  const url = str(o.url, 1000);
  if (!IMAGE_HOST.test(url)) return null; // only images we fetched from Commons
  return {
    url,
    width: num(o.width, 1024, 1, 10000),
    height: num(o.height, 768, 1, 10000),
    title: str(o.title, 300),
    credit: str(o.credit, 300),
    license: str(o.license, 100),
    page: /^https:\/\/commons\.wikimedia\.org\//.test(str(o.page, 1000)) ? str(o.page, 1000) : '',
  };
}

function parseDiagram(value: unknown, strict: boolean): SlideDiagram | null {
  const o = obj(value);
  if (!DIAGRAM_KINDS.includes(o.kind as DiagramKind)) return null;
  const items: DiagramItem[] = (Array.isArray(o.items) ? o.items : [])
    .map(i => {
      const x = obj(i);
      return { emoji: str(x.emoji, 16), label: str(x.label, 80), detail: str(x.detail, 160) };
    })
    // the editor keeps half-typed items; AI output must have labels
    .filter(i => (strict ? i.label : i.label || i.emoji || i.detail))
    .slice(0, 6);
  if (strict && items.length < 2) return null;
  return { kind: o.kind as DiagramKind, items };
}

export function parseQuiz(value: unknown, strict = true): QuizContent | null {
  const raw = obj(value);
  const list = Array.isArray(raw.questions) ? raw.questions : Array.isArray(value) ? (value as unknown[]) : [];
  const questions: QuizQuestion[] = [];
  for (const q of list) {
    const o = obj(q);
    const type: QuestionType = o.type === 'truefalse' || o.type === 'short' ? o.type : 'mcq';
    const question = str(o.question, 1000);
    if (!question) continue;
    let options = strList(o.options, 6);
    if (type === 'truefalse') options = ['True', 'False'];
    if (type === 'short') options = [];
    if (type === 'mcq' && options.length < 2) continue;
    const correct = type === 'short' ? -1 : num(o.correct, 0, 0, options.length - 1);
    questions.push({
      type, question, options, correct,
      answer: str(o.answer, 1000),
      explanation: str(o.explanation, 1000),
      marks: num(o.marks, 1, 1, 10),
    });
  }
  if (questions.length < (strict ? 2 : 1)) return null;
  const difficulty = raw.difficulty === 'easy' || raw.difficulty === 'hard' ? raw.difficulty : 'medium';
  return { instructions: str(raw.instructions, 1000), difficulty, questions: questions.slice(0, 50) };
}

export function parseLesson(value: unknown, strict = true): LessonContent | null {
  const raw = obj(value);
  const sections: LessonSection[] = (Array.isArray(raw.sections) ? raw.sections : []).map(s => {
    const o = obj(s);
    return {
      title: str(o.title, 200) || 'Activity',
      minutes: num(o.minutes, 5, 1, 180),
      teacher: str(o.teacher, 2000),
      students: str(o.students, 2000),
    };
  });
  const objectives = strList(raw.objectives);
  if (strict && (sections.length < 2 || objectives.length < 1)) return null;
  if (!sections.length) return null;
  return {
    duration: num(raw.duration, sections.reduce((t, s) => t + s.minutes, 0), 10, 240),
    objectives,
    prerequisites: strList(raw.prerequisites),
    materials: strList(raw.materials),
    sections: sections.slice(0, 15),
    assessment: strList(raw.assessment),
    homework: strList(raw.homework),
    differentiation: str(raw.differentiation),
    boardWork: str(raw.boardWork),
  };
}

export const PARSERS = { slides: parseSlides, quiz: parseQuiz, lesson: parseLesson } as const;

/** Validators for saving edits to any teacher doc type (PATCH /api/teacher/docs/[id]). */
export const DOC_PARSERS: Record<DocType, (value: unknown, strict?: boolean) => unknown> = { ...PARSERS, exam: parseExam };

// ── Prompts ──────────────────────────────────────────────────────────

export interface GenerateOptions {
  topic: string;
  grade: string;
  language: string;
  slideCount?: number;
  questionCount?: number;
  difficulty?: 'easy' | 'medium' | 'hard';
  duration?: number;
  extra?: string;
  /** Uploaded material (syllabus, notes, PPT, chapter) to base the document on. */
  sources?: SourceFile[];
}

/** Prompt budget for uploaded material (characters). */
const SOURCE_CHARS = 22_000;

const FOLLOW_SOURCE: Record<GeneratedDocType, string> = {
  slides: 'Build the deck from the SOURCE MATERIAL: follow its sequence of sub-topics, use its definitions, examples, numbers and diagrams (as "diagram"/"image" slides) and cover its key points for this topic. The structure below is a guide; adapt it to the material.',
  quiz: 'Write every question from the SOURCE MATERIAL: test its facts, definitions, terms, examples and numericals, so each answer can be found in or worked out from it, at its level. Explanations may say where in the material the answer comes from.',
  lesson: 'Plan the period around the SOURCE MATERIAL: teach its points for this topic in its order, use its examples and activities, and align the objectives, board work and assessment with it.',
};

function languageLine(language: string) {
  return language === 'English'
    ? 'Write everything in clear, simple English.'
    : `Write all student-facing text in ${language} (native script). Keep scientific terms, formulas and symbols in English where that is how Indian textbooks write them.`;
}

export function buildPrompt(type: GeneratedDocType, o: GenerateOptions): string {
  const material = sourceBlock(o.sources ?? [], o.topic, SOURCE_CHARS);
  const context = `Topic: "${o.topic}"
Class/grade: ${o.grade} (Indian CBSE/NCERT level)
${languageLine(o.language)}
${o.extra ? `Teacher's notes: ${o.extra}\n` : ''}${material ? `${material}${FOLLOW_SOURCE[type]}\n` : ''}`;

  if (type === 'slides') {
    const n = o.slideCount ?? 10;
    return `Create a highly VISUAL classroom lecture slide deck of exactly ${n} slides. A young child should understand the topic just by looking at the pictures and diagrams, and the teacher should find it easy to teach from.
${context}
Structure: slide 1 is a "title" slide; then hook/why-it-matters, prerequisites recap, core concept slides (definitions, formulas, step-by-step worked example, real-life Indian examples), a common-mistakes slide, a quick check-your-understanding slide, and a final "summary" slide.

VISUALS — every slide must carry a visual:
- "emoji": one emoji that captures the slide (every slide).
- "image" layout for real things a child should SEE (plants, organs, animals, places, monuments, people, apparatus, maps). Put precise English search terms for Wikimedia Commons in "imageQuery", 2-6 words, e.g. "leaf cross section diagram", "human heart anatomy diagram", "Qutub Minar", "litmus paper test". Prefer labelled diagrams for science.
- "diagram" layout for processes, cycles, steps, cause→effect, classifications: fill "diagram" = {"kind": "flow" (steps in order) | "cycle" (repeats in a loop) | "cards" (a set of related ideas), "items": 3-6 × {"emoji","label" (max 4 words),"detail" (max 12 words)}}.
- Title, bullets, summary and quote slides should also get an "imageQuery" when a picture would help.
- At least half of the slides must be "image" or "diagram" slides. Use "two-column" only for comparisons.
- Labels, details and bullets are in the slide language; imageQuery is ALWAYS in English.

Keep bullets short (max 12 words, 2-4 per slide; 1-2 on image/diagram slides). Put the detailed explanation the teacher should SAY in "notes". In "visual", describe in one line what to point at on the visual.
Use "two-column" for comparisons (fill "bullets" = left column, "right" = right column) and "quote" for a key definition or law (put it in "subtitle").

Return ONLY JSON:
{"theme":"saffron","slides":[{"layout":"title|bullets|image|diagram|two-column|quote|summary","emoji":"🌱","title":"...","subtitle":"...","bullets":["..."],"right":["..."],"imageQuery":"...","diagram":{"kind":"flow","items":[{"emoji":"☀️","label":"...","detail":"..."}]},"visual":"...","notes":"..."}]}`;
  }

  if (type === 'quiz') {
    const n = o.questionCount ?? 10;
    return `Create a ${o.difficulty ?? 'medium'} difficulty quiz with exactly ${n} questions.
${context}
Mix: about 60% "mcq" (exactly 4 options, one correct), 20% "truefalse", 20% "short" (1-3 line answers). Test understanding and application, not just recall. Avoid "all of the above". Every question needs an explanation.
"correct" is the 0-based index of the right option (use -1 for short). For short questions put the model answer in "answer". Give 1 mark per mcq/truefalse and 2-3 marks per short question.

Return ONLY JSON:
{"instructions":"...","difficulty":"${o.difficulty ?? 'medium'}","questions":[{"type":"mcq|truefalse|short","question":"...","options":["..."],"correct":0,"answer":"...","explanation":"...","marks":1}]}`;
  }

  const minutes = o.duration ?? 40;
  return `Create a detailed, practical lesson plan for one ${minutes}-minute class period.
${context}
Sections must add up to ${minutes} minutes and follow: engage/hook → recall prior knowledge → explain (with a worked example) → guided practice → independent practice/activity → assessment/exit ticket → wrap-up. For each section say exactly what the TEACHER does/says and what STUDENTS do. Objectives must be measurable (Students will be able to ...). Include differentiation for weaker and advanced students and what to write on the blackboard.

Return ONLY JSON:
{"duration":${minutes},"objectives":["..."],"prerequisites":["..."],"materials":["..."],"sections":[{"title":"...","minutes":5,"teacher":"...","students":"..."}],"assessment":["..."],"homework":["..."],"differentiation":"...","boardWork":"..."}`;
}
